// Initialize Bootstrap carousel for EAV records
// Must reinitialize after HTMX loads content
(function () {
    function initCarousel() {
        const carouselEl = document.getElementById('recordsCarousel');
        if (!carouselEl) return;

        // Check if already initialized
        if (carouselEl.dataset.bsInitialized) return;

        if (typeof bootstrap !== 'undefined' && bootstrap.Carousel) {
            const carousel = new bootstrap.Carousel(carouselEl, {
                interval: false,
                ride: false,
                wrap: true
            });
            carouselEl.dataset.bsInitialized = 'true';
        }
    }

    // Try on DOMContentLoaded
    document.addEventListener('DOMContentLoaded', initCarousel);

    // Reinitialize after HTMX swaps content (this is the key fix)
    document.body.addEventListener('htmx:afterSwap', function (event) {
        if (event.detail.target.id === 'records-container') {
            // Small delay to ensure DOM is fully updated
            setTimeout(initCarousel, 50);
        }
    });
})();
